#!/usr/bin/env python3
"""Isolate native BERT math, quantization and the original phone expansion."""

import argparse
import copy
import ctypes as ct
import json
import os
from pathlib import Path
import sys

from melotts_decoder import comparison, guard
from melotts_inputs import SOURCES, TOKENIZER_REVISION, select_functions, sha

TRANSFORMERS = "4.57.1"
BERT_SOURCE_SHA = "89e5e5098b98a206c8835c6c00b52b40d6d078a5994c40f300f98173969137c2"
ORIGINAL_MODEL_SHA = "68d45e234eb4a928074dfd868cead0219ab85354cc53d20e772753c6bb9169d3"
TEXTS = [
    "This audio was generated by artificial intelligence.",
    "The quick brown fox jumps over the lazy dog.",
    "We enjoy reading books and listening to music in the evening.",
]


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("--library", type=Path, required=True)
    p.add_argument("--bert-q4", type=Path, required=True)
    p.add_argument("--bert-f16", type=Path, required=True)
    p.add_argument("--captures", type=Path, required=True)
    p.add_argument("--output", type=Path, required=True)
    args = p.parse_args()
    if (
        not Path("/kaggle/working").is_dir()
        or os.environ.get("CRISPASR_DECODER_READY") != "1"
    ):
        raise RuntimeError("Hosted GPU diagnostic only")
    guard(args.output.parent)
    os.environ.update(USE_TF="0", USE_FLAX="0")
    import numpy as np
    import torch
    import transformers
    from transformers import AutoModelForMaskedLM, AutoTokenizer, BertModel
    from transformers.models.bert import modeling_bert
    from huggingface_hub import hf_hub_download
    from gguf import GGUFReader
    from gguf.quants import dequantize

    if (
        transformers.__version__ != TRANSFORMERS
        or sha(modeling_bert.__file__) != BERT_SOURCE_SHA
    ):
        raise ValueError("Original BERT implementation differs from pinned source")
    if not torch.cuda.is_available():
        raise RuntimeError("Original BERT must actually run on CUDA")
    torch.set_num_threads(2)
    torch.backends.cuda.matmul.allow_tf32 = False
    torch.backends.cudnn.allow_tf32 = False
    args.output.mkdir(parents=True, exist_ok=True)
    receipt = dict(
        complete=False,
        application_acceptance=False,
        full_neural_parity=False,
        scope="BERT boundary only: shared dequantized GGUF weights and separate original full-precision checkpoint",
        transformers=TRANSFORMERS,
        modeling_bert_sha256=BERT_SOURCE_SHA,
        original_revision=TOKENIZER_REVISION,
        original_model_sha256=ORIGINAL_MODEL_SHA,
        native_backend="CPU",
        reference_backend="CUDA",
        comparisons=[],
        resource_checks=[],
    )

    def save():
        (args.output / "bert-controls.json").write_text(json.dumps(receipt, indent=2))

    def headroom(label):
        receipt["resource_checks"].append(dict(phase=label, **guard(args.output)))
        save()

    tokenizer = AutoTokenizer.from_pretrained(
        "google-bert/bert-base-uncased", revision=TOKENIZER_REVISION
    )
    headroom("download-original-checkpoint")
    weights = hf_hub_download(
        "google-bert/bert-base-uncased",
        "model.safetensors",
        revision=TOKENIZER_REVISION,
    )
    if sha(weights) != ORIGINAL_MODEL_SHA:
        raise ValueError("Original BERT checkpoint checksum changed")
    for name in ["LICENSE", "config.json"]:
        path = hf_hub_download(
            "google-bert/bert-base-uncased", name, revision=TOKENIZER_REVISION
        )
        (args.output / ("original-bert-" + name)).write_bytes(Path(path).read_bytes())
    headroom("load-original-bert")
    original = (
        AutoModelForMaskedLM.from_pretrained(
            "google-bert/bert-base-uncased",
            revision=TOKENIZER_REVISION,
            use_safetensors=True,
            attn_implementation="eager",
        )
        .eval()
        .cuda()
    )
    english = args.captures / "oracle-source/melo/text/english_bert.py"
    if sha(english) != SOURCES["melo/text/english_bert.py"]:
        raise ValueError("Original phone expansion source changed")
    namespace = dict(sys=sys, torch=torch, model=original, tokenizer=tokenizer)
    select_functions(english, {"get_bert_feature"}, namespace)
    original_features = []
    token_ids = []
    counts = []
    for i, text in enumerate(TEXTS):
        headroom("original-phone-features-" + str(i))
        case = args.captures / ("case-" + str(i))
        ids = np.fromfile(case / "bert_token_ids.bin", dtype="<i4")
        word2ph = np.fromfile(case / "bert_word2ph.bin", dtype="<i4").tolist()
        if not np.array_equal(ids, tokenizer(text)["input_ids"]):
            raise ValueError("Original and native BERT token IDs differ")
        feature = (
            namespace["get_bert_feature"](text, word2ph, device="cuda")
            .contiguous()
            .numpy()
        )
        feature.tofile(args.output / (f"case-{i}-original-f32-features.bin"))
        original_features.append(feature)
        token_ids.append(ids)
        counts.append(word2ph)
    config = copy.deepcopy(original.config)
    del original
    namespace["model"] = None
    torch.cuda.empty_cache()
    library = ct.CDLL(str(args.library))
    library.bert_encoder_init.argtypes = [ct.c_char_p, ct.c_int]
    library.bert_encoder_init.restype = ct.c_void_p
    library.bert_encoder_free.argtypes = [ct.c_void_p]
    library.bert_encoder_forward.argtypes = [
        ct.c_void_p,
        ct.c_char_p,
        ct.POINTER(ct.POINTER(ct.c_float)),
        ct.POINTER(ct.c_int),
    ]
    library.bert_encoder_forward.restype = ct.c_bool
    libc = ct.CDLL(None)
    libc.free.argtypes = [ct.c_void_p]
    for label, path in [("q4_k", args.bert_q4), ("f16-control", args.bert_f16)]:
        headroom("load-shared-weights-" + label)
        gguf = GGUFReader(path)
        n_layers = int(gguf.fields["bert.n_layers"].contents())
        if n_layers != 10 or config.num_hidden_layers != 12:
            raise ValueError("Expected original hidden_states[-3] boundary changed")
        truncated = copy.deepcopy(config)
        truncated.num_hidden_layers = n_layers
        reference = BertModel(truncated, add_pooling_layer=False)
        parameters = {}
        for tensor in gguf.tensors:
            array = dequantize(tensor.data, tensor.tensor_type).reshape(
                tuple(reversed(tensor.shape.tolist()))
            )
            parameters[tensor.name] = torch.from_numpy(
                array.astype(np.float32, copy=True)
            )
        reference.load_state_dict(parameters, strict=True)
        del parameters, gguf
        reference = reference.eval().cuda()
        ctx = library.bert_encoder_init(os.fsencode(path), 2)
        if not ctx:
            raise RuntimeError("Native BERT control initialization failed")
        try:
            for i, text in enumerate(TEXTS):
                headroom(label + "-boundary-" + str(i))
                pointer = ct.POINTER(ct.c_float)()
                size = ct.c_int()
                if not library.bert_encoder_forward(
                    ctx, text.encode(), ct.byref(pointer), ct.byref(size)
                ):
                    raise RuntimeError("Native BERT control failed")
                try:
                    if size.value != len(token_ids[i]):
                        raise ValueError("Native token shape changed")
                    native = (
                        np.ctypeslib.as_array(pointer, shape=(size.value * 768,))
                        .copy()
                        .reshape(size.value, 768)
                    )
                finally:
                    libc.free(pointer)
                with torch.inference_mode():
                    tokens = torch.tensor(
                        token_ids[i].astype(np.int64)[None], device="cuda"
                    )
                    # Ten stored layers end at the full original model's [-3].
                    result = reference(tokens).last_hidden_state[0].cpu()
                    expanded = (
                        torch.repeat_interleave(result, torch.tensor(counts[i]), dim=0)
                        .T.contiguous()
                        .numpy()
                    )
                native_expanded = np.repeat(
                    native, np.asarray(counts[i]), axis=0
                ).T.copy()
                native_expanded.tofile(
                    args.output / (f"case-{i}-{label}-native-features.bin")
                )
                expanded.tofile(
                    args.output / (f"case-{i}-{label}-original-shared-features.bin")
                )
                metrics = dict(
                    profile=label,
                    case=i,
                    model_sha256=sha(path),
                    native_vs_shared_weights=comparison(native_expanded, expanded),
                    native_vs_original_f32=comparison(
                        native_expanded, original_features[i]
                    ),
                )
                if label == "q4_k":
                    existing = np.fromfile(
                        args.captures / f"case-{i}/ja_bert_features.bin", dtype="<f4"
                    ).reshape(768, -1)
                    metrics["native_capture_repeat_exact"] = bool(
                        np.array_equal(existing, native_expanded)
                    )
                receipt["comparisons"].append(metrics)
                save()
        finally:
            library.bert_encoder_free(ctx)
        del reference
        torch.cuda.empty_cache()
    receipt["complete"] = True
    save()


if __name__ == "__main__":
    main()
